import{_ as o,c as t,o as e,a4 as n}from"./chunks/framework.BYxathSa.js";const p=JSON.parse('{"title":"Q22：XSS 与 CSRF 攻击的原理和防御","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q22.md","filePath":"frontend/q22.md","lastUpdated":null}'),i={name:"frontend/q22.md"},r=n('<h1 id="q22-xss-与-csrf-攻击的原理和防御" tabindex="-1">Q22：XSS 与 CSRF 攻击的原理和防御 <a class="header-anchor" href="#q22-xss-与-csrf-攻击的原理和防御" aria-label="Permalink to &quot;Q22：XSS 与 CSRF 攻击的原理和防御&quot;">​</a></h1><ul><li><p><strong>XSS（跨站脚本攻击）</strong></p><ul><li><strong>原理</strong>：攻击者将恶意脚本注入到网页中，当用户浏览时脚本执行，窃取信息或冒充用户。</li><li><strong>类型</strong>：存储型（存到数据库）、反射型（URL 参数）、DOM 型（前端脚本漏洞）。</li><li><strong>防御</strong>： <ul><li>对所有用户输入进行<strong>转义/过滤</strong>。</li><li>使用 <code>CSP</code>（内容安全策略）限制脚本来源。</li><li>Cookie 设置 <code>HttpOnly</code>，防止 JS 读取。</li><li>使用安全的 DOM 操作 API（如 <code>textContent</code> 替代 <code>innerHTML</code>）。</li></ul></li></ul></li><li><p><strong>CSRF（跨站请求伪造）</strong></p><ul><li><strong>原理</strong>：用户登录某信任站点 A 后，在没有登出的情况下访问了恶意网站 B，B 诱导用户向站点 A 发起非预期的请求（如转账），由于携带了有效 Cookie，请求被认为合法。</li><li><strong>防御</strong>： <ul><li><strong>Token 校验</strong>：前端请求携带服务端生成的随机 Token，且不存入 Cookie。</li><li><strong>SameSite Cookie</strong>：设置 <code>SameSite: Strict</code> 或 <code>Lax</code>，跨站请求不携带。</li><li><strong>验证 Referer/Origin 头</strong>：判断请求来源是否合法。</li><li><strong>双重 Cookie 验证</strong>：请求中将某个值写入 Header 并与 Cookie 对比。</li></ul></li></ul></li></ul>',2),l=[r];function s(a,c,d,_,g,S){return e(),t("div",null,l)}const f=o(i,[["render",s]]);export{p as __pageData,f as default};
